// GENERATED BY SYMPLRV3 — DO NOT EDIT
// Bridges reanimated < 4.3's legacy libworklets.so import path on Android.
// Why: Expo SDK 54 pins reanimated ~4.1.1 + worklets 0.5.1 (the Expo
// Go-matched pairing, which must not be bumped — reanimated throws on a
// JS/native version mismatch in Expo Go). reanimated < 4.3 links
// libworklets.so from the legacy AGP layout
// <worklets>/android/build/intermediates/cmake/<type>/obj/<ABI>/ which
// modern AGP never writes, so release builds fail at reanimated's native
// link. This plugin stages the .so where reanimated expects it. Self-noops
// once the SDK ships reanimated >= 4.3 (prefab consumption).
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// SYMPLRV3 WORKLETS PAIRING';

const SNIPPET = `
// SYMPLRV3 WORKLETS PAIRING BEGIN (added by plugins/with-worklets-pairing.js)
gradle.projectsEvaluated {
  def worklets = rootProject.findProject(':react-native-worklets')
  def reanimated = rootProject.findProject(':react-native-reanimated')
  if (worklets != null && reanimated != null) {
    def reanimatedCmake = new File(reanimated.projectDir, 'CMakeLists.txt')
    // reanimated >= 4.3 consumes worklets via prefab — nothing to bridge.
    if (reanimatedCmake.exists() && reanimatedCmake.text.contains('intermediates/cmake')) {
      def workletsBuild = worklets.layout.buildDirectory.get().asFile
      def workletsCxxStaging = new File(worklets.projectDir, '.cxx')
      ['debug', 'release'].each { String type ->
        def isDebug = (type == 'debug')
        def stage = worklets.tasks.register('symplrStageWorkletsSo' + type.capitalize()) {
          def outBase = new File(workletsBuild, 'intermediates/cmake/' + type + '/obj')
          outputs.upToDateWhen { false }
          doLast {
            def found = [:]
            [new File(workletsBuild, 'intermediates/cxx'), workletsCxxStaging].each { root ->
              if (root.directory) {
                root.eachFileRecurse(groovy.io.FileType.FILES) { f ->
                  if (f.name == 'libworklets.so') {
                    def abi = f.parentFile.name
                    def prev = found[abi]
                    if (prev == null || f.lastModified() > prev.lastModified()) { found[abi] = f }
                  }
                }
              }
            }
            if (found.isEmpty()) {
              logger.warn('[symplrv3] libworklets.so not found under ' + workletsBuild + ' — reanimated may fail to link')
            }
            found.each { abi, f ->
              def dst = new File(outBase, abi + '/libworklets.so')
              dst.parentFile.mkdirs()
              dst.bytes = f.bytes
            }
          }
        }
        // after worklets' own native build of the SAME build type…
        // (release CMake tasks are named RelWithDebInfo — 'Debug' only
        // matches the debug variant's tasks; externalNativeBuildClean<Type>
        // must NOT match, or depending on it schedules the clean, which
        // gradle is free to run right after the build — wiping the .so
        // this task exists to stage)
        worklets.tasks.matching { t ->
          !t.name.contains('Clean') && (t.name.startsWith('buildCMake') || t.name.startsWith('externalNativeBuild')) && (isDebug == t.name.contains('Debug'))
        }.all { t -> stage.configure { it.dependsOn(t) } }
        // …and before reanimated's CMake configure/build touches the import.
        // (Clean excluded here too — cleaning reanimated must not drag the
        // whole worklets native build in as a dependency.)
        reanimated.tasks.matching { t ->
          !t.name.contains('Clean') && (t.name.startsWith('configureCMake') || t.name.startsWith('buildCMake') || t.name.startsWith('externalNativeBuild')) && (isDebug == t.name.contains('Debug'))
        }.all { t -> t.dependsOn(stage) }
      }
    }
  }
}
// SYMPLRV3 WORKLETS PAIRING END
`;

module.exports = function withWorkletsPairing(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (!cfg.modResults.contents.includes(MARKER)) {
      cfg.modResults.contents += '\n' + SNIPPET;
    }
    return cfg;
  });
};
